import{_ as o,o as i,c as t,ae as a}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Envelope Schema, Types, and Validation","description":"","frontmatter":{"work_package_id":"WP01","title":"Envelope Schema, Types, and Validation","lane":"done","dependencies":[],"base_branch":"main","base_commit":"d89dc4f54d56d98a0ded78813aeffc0ed68d1dd0","created_at":"2026-02-27T11:19:15.585730+00:00","subtasks":["T001","T002","T003","T004","T005","T006"],"phase":"Phase 1 - Foundation","assignee":"","agent":"wp01-bus-agent","shell_pid":"22522","reviewed_by":"Koosha Paridehpour","review_status":"approved"},"headers":[],"relativePath":"specs/002-local-bus-v1-protocol-and-envelope/tasks/WP01-envelope-schema-types-and-validation.md","filePath":"specs/002-local-bus-v1-protocol-and-envelope/tasks/WP01-envelope-schema-types-and-validation.md"}'),l={name:"specs/002-local-bus-v1-protocol-and-envelope/tasks/WP01-envelope-schema-types-and-validation.md"};function s(r,e,n,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="work-package-prompt-wp01-envelope-schema-types-and-validation" tabindex="-1">Work Package Prompt: WP01 - Envelope Schema, Types, and Validation <a class="header-anchor" href="#work-package-prompt-wp01-envelope-schema-types-and-validation" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Envelope Schema, Types, and Validation&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Define the canonical envelope schema that every bus message must conform to.</li><li>Establish discriminated union types for command, response, and event envelopes.</li><li>Implement strict validation that rejects malformed envelopes before routing.</li><li>Define the error taxonomy used throughout the bus subsystem.</li><li>Publish JSON schema assets for external tooling and cross-repo validation.</li></ul><p>Success criteria:</p><ul><li>All envelope types compile with strict TypeScript checks.</li><li>Validation rejects 100% of malformed payloads with structured errors.</li><li>JSON schema and runtime types are provably aligned.</li><li>Error taxonomy covers all bus failure modes: <code>VALIDATION_ERROR</code>, <code>METHOD_NOT_FOUND</code>, <code>HANDLER_ERROR</code>, <code>TIMEOUT</code>, <code>BACKPRESSURE</code>.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/002-local-bus-v1-protocol-and-envelope/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/002-local-bus-v1-protocol-and-envelope/spec.md</code></li><li>Existing protocol code: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/types.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/bus.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/specs/protocol/v1/</code></li></ul></li></ul><p>Constraints:</p><ul><li>Fail-fast validation: no silent fallback or partial acceptance.</li><li>Payload size limit configurable, default 1 MB.</li><li>Keep files under 350 lines (hard limit 500).</li><li>IDs use spec 005 format (<code>{prefix}_{ulid}</code>) — import from <code>packages/ids/</code> when available, stub if not.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-define-envelope-typescript-interfaces-and-discriminated-unions" tabindex="-1">Subtask T001 - Define envelope TypeScript interfaces and discriminated unions <a class="header-anchor" href="#subtask-t001-define-envelope-typescript-interfaces-and-discriminated-unions" aria-label="Permalink to &quot;Subtask T001 - Define envelope TypeScript interfaces and discriminated unions&quot;">​</a></h3><ul><li>Purpose: establish the core type contract that all bus consumers depend on.</li><li>Steps: <ol><li>Open <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/types.ts</code>.</li><li>Define a base <code>EnvelopeBase</code> interface with fields: <code>id: string</code>, <code>correlation_id: string</code>, <code>timestamp: number</code>, <code>sequence?: number</code>.</li><li>Define <code>CommandEnvelope</code> extending base with <code>type: &#39;command&#39;</code>, <code>method: string</code>, <code>payload: unknown</code>.</li><li>Define <code>ResponseEnvelope</code> extending base with <code>type: &#39;response&#39;</code>, <code>method: string</code>, <code>payload: unknown</code>, <code>error?: BusError</code>.</li><li>Define <code>EventEnvelope</code> extending base with <code>type: &#39;event&#39;</code>, <code>topic: string</code>, <code>payload: unknown</code>, <code>sequence: number</code>.</li><li>Export discriminated union <code>Envelope = CommandEnvelope | ResponseEnvelope | EventEnvelope</code>.</li><li>Export type guards: <code>isCommand(e)</code>, <code>isResponse(e)</code>, <code>isEvent(e)</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/types.ts</code></li></ul></li><li>Validation checklist: <ul><li>[ ] All three envelope shapes compile under <code>strict: true</code>.</li><li>[ ] Type guards narrow correctly in conditional blocks.</li><li>[ ] <code>Envelope</code> union covers exactly three members.</li></ul></li><li>Edge cases: <ul><li>Ensure <code>payload: unknown</code> (not <code>any</code>) to force consumer type narrowing.</li><li><code>sequence</code> is optional on command/response, required on events.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-define-error-taxonomy-types-and-constructors" tabindex="-1">Subtask T002 - Define error taxonomy types and constructors <a class="header-anchor" href="#subtask-t002-define-error-taxonomy-types-and-constructors" aria-label="Permalink to &quot;Subtask T002 - Define error taxonomy types and constructors&quot;">​</a></h3><ul><li>Purpose: provide structured error representation for all bus failure modes.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/errors.ts</code>.</li><li>Define <code>BusErrorCode</code> string literal union: <code>&#39;VALIDATION_ERROR&#39; | &#39;METHOD_NOT_FOUND&#39; | &#39;HANDLER_ERROR&#39; | &#39;TIMEOUT&#39; | &#39;BACKPRESSURE&#39;</code>.</li><li>Define <code>BusError</code> interface: <code>{ code: BusErrorCode; message: string; details?: unknown }</code>.</li><li>Implement factory functions: <code>validationError(message, details?)</code>, <code>methodNotFound(method)</code>, <code>handlerError(method, cause)</code>, <code>timeoutError(method, timeoutMs)</code>, <code>backpressureError(topic)</code>.</li><li>Each factory returns a frozen <code>BusError</code> object.</li><li>Export all types and factories.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/errors.ts</code></li></ul></li><li>Validation checklist: <ul><li>[ ] All five error codes have corresponding factory functions.</li><li>[ ] Factory return types are <code>Readonly&lt;BusError&gt;</code>.</li><li>[ ] Factories never throw — they produce error values.</li></ul></li><li>Edge cases: <ul><li><code>details</code> on <code>HANDLER_ERROR</code> must sanitize stack traces (no file system paths in production).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-envelope-creation-helpers" tabindex="-1">Subtask T003 - Implement envelope creation helpers <a class="header-anchor" href="#subtask-t003-implement-envelope-creation-helpers" aria-label="Permalink to &quot;Subtask T003 - Implement envelope creation helpers&quot;">​</a></h3><ul><li>Purpose: provide a single entry point for creating well-formed envelopes with auto-generated IDs and timestamps.</li><li>Steps: <ol><li>Create or update <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/envelope.ts</code>.</li><li>Implement <code>createCommand(method, payload, correlationId?)</code>: generates <code>id</code> (using spec 005 or stub), sets <code>correlation_id</code> (generate if not provided), sets <code>timestamp</code> from monotonic clock, returns <code>CommandEnvelope</code>.</li><li>Implement <code>createResponse(command, payload, error?)</code>: copies <code>correlation_id</code> and <code>method</code> from originating command, generates new <code>id</code>, returns <code>ResponseEnvelope</code>.</li><li>Implement <code>createEvent(topic, payload, correlationId?, sequence?)</code>: generates <code>id</code>, sets <code>correlation_id</code>, sets <code>timestamp</code>, returns <code>EventEnvelope</code>. Sequence is set by topic registry at publish time, not by caller.</li><li>All helpers validate their inputs before constructing the envelope.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/envelope.ts</code></li></ul></li><li>Validation checklist: <ul><li>[ ] <code>createCommand</code> without correlationId auto-generates one.</li><li>[ ] <code>createResponse</code> always carries the originating command&#39;s correlation_id.</li><li>[ ] <code>createEvent</code> leaves sequence as 0 (placeholder for topic registry assignment).</li><li>[ ] All timestamps use monotonic clock source.</li></ul></li><li>Edge cases: <ul><li>If spec 005 ID library is not yet available, implement a temporary ULID stub with TODO marker.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-strict-envelope-validation" tabindex="-1">Subtask T004 - Implement strict envelope validation <a class="header-anchor" href="#subtask-t004-implement-strict-envelope-validation" aria-label="Permalink to &quot;Subtask T004 - Implement strict envelope validation&quot;">​</a></h3><ul><li>Purpose: gate all bus routing behind schema validation to prevent malformed messages from propagating.</li><li>Steps: <ol><li>In <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/envelope.ts</code>, implement <code>validateEnvelope(envelope: unknown): { valid: true; envelope: Envelope } | { valid: false; error: BusError }</code>.</li><li>Check required fields: <code>id</code> (non-empty string), <code>correlation_id</code> (non-empty string), <code>type</code> (one of &#39;command&#39;|&#39;response&#39;|&#39;event&#39;), <code>timestamp</code> (positive number).</li><li>For commands: require <code>method</code> (non-empty string) and <code>payload</code>.</li><li>For events: require <code>topic</code> (non-empty string) and <code>payload</code>.</li><li>Check payload size: <code>JSON.stringify(payload).length &lt;= MAX_PAYLOAD_SIZE</code> (configurable, default 1 MB).</li><li>Return <code>validationError</code> from error taxonomy on any failure.</li><li>Export <code>MAX_PAYLOAD_SIZE</code> as configurable constant.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/envelope.ts</code></li></ul></li><li>Validation checklist: <ul><li>[ ] Missing <code>id</code> returns VALIDATION_ERROR.</li><li>[ ] Missing <code>correlation_id</code> returns VALIDATION_ERROR.</li><li>[ ] Unknown <code>type</code> returns VALIDATION_ERROR.</li><li>[ ] Oversized payload returns VALIDATION_ERROR with size info.</li><li>[ ] Valid envelopes return the narrowed typed envelope.</li></ul></li><li>Edge cases: <ul><li><code>payload</code> of <code>undefined</code> vs <code>null</code> — both are acceptable (present but empty).</li><li>Circular references in payload must not crash validation (catch JSON.stringify errors).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t005-create-json-schema-assets" tabindex="-1">Subtask T005 - Create JSON schema assets <a class="header-anchor" href="#subtask-t005-create-json-schema-assets" aria-label="Permalink to &quot;Subtask T005 - Create JSON schema assets&quot;">​</a></h3><ul><li>Purpose: provide machine-readable schema for external tooling, documentation, and cross-repo validation.</li><li>Steps: <ol><li>Create or update <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/specs/protocol/v1/envelope.schema.json</code>.</li><li>Define JSON Schema draft-07 with <code>oneOf</code> for command, response, and event shapes.</li><li>Include all required fields matching T001 type definitions exactly.</li><li>Add <code>maxLength</code> constraint on payload matching <code>MAX_PAYLOAD_SIZE</code>.</li><li>Include <code>enum</code> constraint for <code>type</code> field.</li><li>Add schema <code>$id</code> and <code>title</code> metadata.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/specs/protocol/v1/envelope.schema.json</code></li></ul></li><li>Validation checklist: <ul><li>[ ] Schema validates all three envelope shapes.</li><li>[ ] Schema rejects payloads missing required fields.</li><li>[ ] Schema <code>$id</code> follows convention.</li></ul></li><li>Edge cases: <ul><li>Ensure <code>additionalProperties: false</code> is NOT set at top level to allow forward compat.</li></ul></li><li>Parallel: Yes (after T001 types are stable).</li></ul><h3 id="subtask-t006-add-vitest-unit-tests-for-envelope-and-error-taxonomy" tabindex="-1">Subtask T006 - Add Vitest unit tests for envelope and error taxonomy <a class="header-anchor" href="#subtask-t006-add-vitest-unit-tests-for-envelope-and-error-taxonomy" aria-label="Permalink to &quot;Subtask T006 - Add Vitest unit tests for envelope and error taxonomy&quot;">​</a></h3><ul><li>Purpose: lock envelope creation, validation, and error behavior before higher-level routing work.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/protocol/envelope.test.ts</code>.</li><li>Test <code>createCommand</code>: generates unique IDs, auto-generates correlation_id, sets timestamp.</li><li>Test <code>createResponse</code>: carries originating correlation_id, references method.</li><li>Test <code>createEvent</code>: sets type=&#39;event&#39;, topic, placeholder sequence.</li><li>Test <code>validateEnvelope</code>: positive cases for all three shapes; negative cases for missing id, missing correlation_id, unknown type, oversized payload, circular payload.</li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/protocol/errors.test.ts</code>.</li><li>Test all five error factory functions: correct code, frozen object, message content.</li><li>Add FR traceability comments: <code>// FR-001</code>, <code>// FR-006</code>, <code>// FR-007</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/protocol/envelope.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/protocol/errors.test.ts</code></li></ul></li><li>Validation checklist: <ul><li>[ ] &gt;= 20 test cases covering positive and negative paths.</li><li>[ ] Every FR referenced in at least one test comment.</li><li>[ ] Tests run in &lt; 5 seconds.</li></ul></li><li>Edge cases: <ul><li>Test with empty string IDs, negative timestamps, NaN sequences.</li></ul></li><li>Parallel: Yes (after T001/T002 are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Run unit tests via <code>bun test</code> / Vitest.</li><li>Cover all envelope shapes and error codes.</li><li>Negative tests outnumber positive tests (defensive validation).</li><li>Keep test fixtures minimal and deterministic.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: JSON schema and TypeScript types diverge.</li><li>Mitigation: T018 (WP03) adds automated parity check; during WP01, manual review is required.</li><li>Risk: payload size check is expensive for large payloads.</li><li>Mitigation: short-circuit on <code>typeof payload !== &#39;object&#39;</code> fast path.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm discriminated union exhaustiveness in type guards.</li><li>Confirm validation rejects every known bad shape.</li><li>Confirm error factories produce immutable objects.</li><li>Confirm no <code>any</code> types in public API surface.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27 – system – lane=planned – Prompt generated.</li><li>2026-02-27T11:19:15Z – wp01-bus-agent – shell_pid=22522 – lane=doing – Assigned agent via workflow command</li><li>2026-02-27T11:24:07Z – wp01-bus-agent – shell_pid=22522 – lane=for_review – Ready for review: Envelope schema types, error taxonomy, creation helpers, strict validation, JSON schema, and 54 unit tests</li><li>2026-03-01T13:20:10Z – wp01-bus-agent – shell_pid=22522 – lane=done – Review passed: auto-approved</li><li>2026-03-01T13:23:19Z – wp01-bus-agent – shell_pid=22522 – lane=done – Merged to main</li></ul>',32)])])}const h=o(l,[["render",s]]);export{m as __pageData,h as default};
